import CloseIcon from "@mui/icons-material/Close";
import DownloadIcon from "@mui/icons-material/Download";
import UploadIcon from "@mui/icons-material/Upload";
import { Button, Dialog, DialogContent, DialogTitle, Grid2, IconButton } from "@mui/material";
import React, { useEffect, useState } from "react";

function Cut300Trainer() {
    const [data, setData] = useState([]); // 存放題目數據
    const [open, setOpen] = useState(false); // 控制 Dialog 開啟/關閉
    const [currentQuestion, setCurrentQuestion] = useState(null); // 存放當前題目
    const [answerStatus, setAnswerStatus] = useState({}); // 記錄每題的回答狀態（correct, wrong, null）
    const [selectedAnswer, setSelectedAnswer] = useState(null); // 記錄使用者選擇的答案

    useEffect(() => {
        fetch(`${process.env.PUBLIC_URL}/cut300.json`)
            .then((response) => {
                if (!response.ok) {
                    throw new Error("無法載入 cut300.json");
                }
                return response.json();
            })
            .then((jsonData) => {
                if (jsonData.cut300questions) {
                    setData(jsonData.cut300questions);
                } else {
                    console.error("JSON 格式錯誤，找不到 cut300questions");
                }
            })
            .catch((error) => {
                console.error("讀取 JSON 失敗:", error);
            });
    }, []);

    // 點擊按鈕開啟彈窗
    const handleOpen = (question) => {
        setCurrentQuestion(question);
        setSelectedAnswer(null);
        setOpen(true);
    };

    // 處理回答
    const handleAnswer = (tile) => {
        if (!currentQuestion) return;
        const isCorrect = tile === currentQuestion.answer;
        setSelectedAnswer(tile);

        // 更新題目回答狀態
        setAnswerStatus((prev) => ({
            ...prev,
            [currentQuestion.questionId]: isCorrect ? "correct" : "incorrect",
        }));
    };

    const handleExport = () => {
        const timestamp = Math.floor(Date.now() / 1000);
        const filename = `cut300-${timestamp}.json`;

        const blob = new Blob([JSON.stringify(answerStatus, null, 2)], { type: "application/json" });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = filename;
        link.click();
    };

    const handleUpload = (event) => {
        const file = event.target.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = () => {
            try {
                const jsonData = JSON.parse(reader.result);
                setAnswerStatus(jsonData);
            } catch (error) {
                console.error("無法解析 JSON", error);
            }
        };
        reader.readAsText(file);
    };

    return (
        <div style={{ maxWidth: "100%", boxSizing: "border-box", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
            <div style={{ fontSize: "clamp(28px, 2vw, 32px)", fontWeight: "bold" }}>何切 300 練習</div>

            <div style={{ display: "flex", justifyContent: "center", gap: "15px", marginTop: "10px", marginBottom: "20px" }}>
                <Button variant="contained" onClick={handleExport} style={{ fontSize: "16px", fontWeight: "bold", backgroundColor: "#007BFF" }}>
                    <DownloadIcon />
                    暫存結果
                </Button>
                <Button variant="contained" component="label" style={{ fontSize: "16px", fontWeight: "bold", backgroundColor: "#007BFF" }}>
                    <UploadIcon />
                    上傳檔案
                    <input type="file" hidden accept=".json" onChange={handleUpload} />
                </Button>
            </div>

            {/* 題目按鈕區域 */}
            <Grid2 container spacing={2} justifyContent="center" style={{ width: "100%", maxWidth: "800px" }}>
                {data.map((q) => (
                    <Grid2 item xs={3} sm={1.5} md={1} key={q.questionId}>
                        <Button
                            variant="contained"
                            onClick={() => handleOpen(q)}
                            style={{
                                backgroundColor: answerStatus[q.questionId] === "correct" ? "#28a745" : answerStatus[q.questionId] === "incorrect" ? "#dc3545" : "#888888",
                            }}
                        >
                            <div style={{ fontSize: "16px", fontWeight: "bold" }}>Q{q.questionId}</div>
                        </Button>
                    </Grid2>
                ))}
            </Grid2>

            {/* 題目彈窗 */}
            <Dialog open={open} onClose={() => setOpen(false)} maxWidth={"md"}>
                {currentQuestion && (
                    <>
                        <DialogTitle
                            sx={{ padding: "clamp(14px, 2vw, 16px) 24px" }}
                            style={{
                                color: answerStatus[currentQuestion.questionId] === "correct" ? "#1B7430FF" : answerStatus[currentQuestion.questionId] === "incorrect" ? "#dc3545" : "#222222",
                                backgroundColor: answerStatus[currentQuestion.questionId] === "correct" ? "#d4edda" : answerStatus[currentQuestion.questionId] === "incorrect" ? "#f8d7da" : "#CCCCCC",
                            }}
                        >
                            <div style={{ fontSize: "clamp(20px, 2vw, 24px)", fontWeight: "bold" }}>Q{currentQuestion.questionId}</div>
                            {/* 右上角關閉按鈕 */}
                            <IconButton
                                aria-label="close"
                                onClick={() => setOpen(false)}
                                sx={{
                                    position: "absolute",
                                    right: 15,
                                    top: 10,
                                    color: (theme) => theme.palette.grey[700],
                                }}
                            >
                                <CloseIcon />
                            </IconButton>
                        </DialogTitle>
                        <DialogContent
                            sx={{ padding: "clamp(8px, 2vw, 16px) clamp(8px, 2vw, 16px)" }}
                            style={{
                                display: "flex",
                                flexDirection: "column",
                                textAlign: "center",
                            }}
                        >
                            <div style={{ fontSize: "clamp(18px, 2vw, 22px)", fontWeight: "bold", marginTop: "10px" }}>
                                {currentQuestion.roundWind}風場 {currentQuestion.seatWind}家 {currentQuestion.turn} 巡目
                            </div>

                            {/* 顯示寶牌 */}
                            <div style={{ display: "flex", justifyContent: "center", flexWrap: "wrap", marginTop: "10px" }}>
                                {[...currentQuestion.doraIndicator, ...Array(5 - currentQuestion.doraIndicator.length).fill("0z")].slice(0, 5).map((tile, index) => (
                                    <img
                                        key={`${tile}-${index}`}
                                        src={`${process.env.PUBLIC_URL}/images/${tile}.png`}
                                        alt={tile}
                                        style={{
                                            width: "7%",
                                            maxWidth: "50px",
                                            aspectRatio: "7 / 10",
                                            borderRadius: "5px",
                                        }}
                                    />
                                ))}
                            </div>

                            {/* 手牌顯示 */}
                            <div className="hand-tiles" style={{ display: "flex", flexWrap: "wrap", marginTop: "10px", justifyContent: "center" }}>
                                {currentQuestion.hands.map((tile, index) => (
                                    <img
                                        key={`${tile}-${index}`}
                                        src={`${process.env.PUBLIC_URL}/images/${tile}.png`}
                                        alt={tile}
                                        style={{
                                            width: "7%",
                                            maxWidth: "50px",
                                            height: "auto",
                                            borderRadius: "5px",
                                        }}
                                    />
                                ))}
                            </div>

                            {/* 選擇切牌按鈕 */}
                            <div style={{ fontSize: "clamp(18px, 2vw, 22px)", fontWeight: "bold", marginTop: "20px" }}>選擇切牌：</div>
                            <div style={{ marginTop: "10px", marginBottom: "20px", width: "100%", display: "flex", justifyContent: "center", flexWrap: "wrap", gap: "6px" }}>
                                {[...new Set(currentQuestion.hands)].map((tile, index) => (
                                    <Button
                                        key={index}
                                        variant="contained"
                                        style={{
                                            width: "6%",
                                            aspectRatio: "7 / 10",
                                            minWidth: "35px",
                                            padding: 0,
                                            display: "inline-flex",
                                            justifyContent: "center",
                                            alignItems: "center",
                                            borderRadius: "5px",
                                            backgroundColor: selectedAnswer === tile ? (tile === currentQuestion.answer ? "green" : "red") : "",
                                        }}
                                        onClick={() => handleAnswer(tile)}
                                    >
                                        <img
                                            src={`${process.env.PUBLIC_URL}/images/${tile}.png`}
                                            alt={tile}
                                            style={{
                                                width: "100%",
                                                height: "100%",
                                                objectFit: "cover",
                                                borderRadius: "5px",
                                            }}
                                        />
                                    </Button>
                                ))}
                            </div>

                            {/* 回答結果 */}
                            {selectedAnswer && (
                                <>
                                    <div
                                        style={{
                                            margin: "10px auto",
                                            padding: "12px 30px",
                                            backgroundColor: selectedAnswer === currentQuestion.answer ? "#d4edda" : "#f8d7da",
                                            border: `3px solid ${selectedAnswer === currentQuestion.answer ? "#28a745" : "#dc3545"}`,
                                            borderRadius: "12px",
                                            textAlign: "center",
                                            fontSize: "clamp(20px, 2vw, 24px)",
                                            fontWeight: "bold",
                                            color: selectedAnswer === currentQuestion.answer ? "#28a745" : "#dc3545",
                                            display: "inline-block",
                                            maxWidth: "90%",
                                            minWidth: "100px",
                                        }}
                                    >
                                        <div>{selectedAnswer === currentQuestion.answer ? "回答正確！" : "回答錯誤！"}</div>
                                        <div style={{ marginTop: "10px", marginBottom: "10px" }}>正確答案：</div>
                                        <img
                                            src={`${process.env.PUBLIC_URL}/images/${currentQuestion.answer}.png`}
                                            alt={currentQuestion.answer}
                                            style={{
                                                width: "6%",
                                                minWidth: "35px",
                                            }}
                                        />
                                    </div>
                                </>
                            )}
                        </DialogContent>
                    </>
                )}
            </Dialog>

            <div style={{ fontSize: "calc(0.7*clamp(28px, 2vw, 32px))", marginTop: "50px" }}>持續更新中</div>
            <img
                src={`${process.env.PUBLIC_URL}/images/user068.png`}
                alt={"user009.png"}
                style={{
                    borderRadius: "20%",
                    border: "1px solid #888888",
                    marginTop: "10px",
                }}
            />
        </div>
    );
}

export default Cut300Trainer;
