const generateWall = () => {
    const types = ["m", "p", "s"];
    const wall = [];

    // 數牌
    types.forEach((type) => {
        for (let num = 1; num <= 9; num++) {
            wall.push(...Array(4).fill(`${num}${type}`));
        }
    });

    // 字牌
    for (let num = 1; num <= 7; num++) {
        wall.push(...Array(4).fill(`${num}z`));
    }

    return wall;
};

const sortTiles = (tiles) => {
    const typeOrder = { m: 0, p: 1, s: 2, z: 3 };

    return [...tiles].sort((a, b) => {
        const aType = a.slice(-1);
        const aNum = a.replace(/\D/g, "");
        const aSortNum = aNum === "0" ? 5.5 : parseInt(aNum, 10);

        const bType = b.slice(-1);
        const bNum = b.replace(/\D/g, "");
        const bSortNum = bNum === "0" ? 5.5 : parseInt(bNum, 10);

        if (typeOrder[aType] !== typeOrder[bType]) {
            return typeOrder[aType] - typeOrder[bType];
        }
        return aSortNum - bSortNum;
    });
};

function canExtractTiles(wall, choice) {
    // 計算 wall 中各張牌的數量
    const wallCount = new Map();
    for (const tile of wall) {
        wallCount.set(tile, (wallCount.get(tile) || 0) + 1);
    }

    // 計算 choice.tiles 需要的數量
    const neededCount = new Map();
    for (const tile of choice.tiles) {
        neededCount.set(tile, (neededCount.get(tile) || 0) + 1);
    }

    // 檢查 wall 中是否有足夠的牌
    for (const [tile, count] of neededCount) {
        if ((wallCount.get(tile) || 0) < count) {
            return false; // 牌數不足
        }
    }
    return true; // 牌數足夠
}

